    "speakGuide": "ଏହି ସୁରକ୍ଷା ନିର୍ଦ୍ଦେଶାବଳୀ ଶୁଣନ୍ତୁ",
    "speakOverview": "ସୁରକ୍ଷା ସାରାଂଶ ଶୁଣନ୍ତୁ",
