        "warning": "ସିଆରଟି କାଚ ଟ୍ୟୁବ୍ ଭିତରେ ଶୂନ୍ୟସ୍ଥାନ (ଭ୍ୟାକ୍ୟୁମ୍) ଥାଏ, ଭାଙ୍ଗିଲେ କାଚ ଖଣ୍ଡଗୁଡ଼ିକ ତୀବ୍ର ବେଗରେ ଛିଟିକିପଡ଼େ।",
